{
  "status": "SUPPORTED",
  "task_summary": "Set up seating, refreshment stations, and remote placement for two people watching TV.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "seating",
        "entity_kind": "OBJECT",
        "function": "Supports the two people who will watch television",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["armchair", "chair"],
        "required_properties": ["stable_surface"]
      },
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Holds refreshments for a single person",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["table", "tray", "side_table"],
        "required_properties": ["holds_refreshments", "near_seating"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Controls the television",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote control", "controller"],
        "required_properties": ["accessible_to_both_people"]
      },
      {
        "id": "television",
        "entity_kind": "FIXED_TARGET",
        "function": "Source of visual entertainment",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["TV", "screen"],
        "required_properties": ["visible_to_seating"]
      }
    ],
    "functional_relations": [
      {
        "id": "facing",
        "relation": "The seating must face the television for viewing",
        "participant_roles": ["seating", "television"]
      ,
      "required": true
      },
      {
        "id": "nearby",
        "relation": "The refreshment setting must be located near the seating for convenience",
        "participant_roles": ["refreshment_setting", "seating"]
      ,
      "required": true
      },
      {
        "id": "accessible_to_both",
        "relation": "The entertainment control must be placed in a spot reachable by both seated people",
        "participant_roles": ["entertainment_control", "seating"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "arrange_refreshments",
        "operation": "Position the refreshment settings near the seating",
        "participant_roles": ["refreshment_setting", "seating"],
        "operation_count": 2
      },
      {
        "id": "position_remote",
        "operation": "Move the entertainment control to a central accessible location",
        "participant_roles": ["entertainment_control", "seating"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
