      {
        "id": "large_desk_surface",
        "label": "Large Desk Surface",
        "visual_description": "Wooden surface holding refreshments and remote, potentially a source for moving items",
        "reason": "Contains items that need to be redistributed according to the task"
      },
      {
        "id": "side_tables",
        "label": "Side Tables Area",
        "visual_description": "Two small wooden tables flanking the armchairs",
        "reason": "Empty surfaces suitable for placing refreshment settings near the seating"
      },
      {
        "id": "rug_center",
        "label": "Rug Center",
        "visual_description": "Light colored rug in the middle of the room",
        "reason": "Potential location for placing the remote to make it accessible to both chairs"
      }
    ],
    "inspection_order": [
      "seating",
      "television",
      "refreshment_setting",
      "entertainment_control"
    ]
  }
